{
  "status": "SUPPORTED",
  "task_summary": "Prepare the living room for two people to enjoy refreshments while watching television. Provide each person with their own refreshment setting nearby, and place the entertainment control where it is accessible to both people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A set of items including a drink vessel and food container for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      , "candidate_categories": ["cup", "plate", "napkin"],
        "required_properties": ["drinkable_vessel", "food_container"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote control"],
        "required_properties": ["button_interface"]
      },
      {
        "id": "side_table",
        "entity_kind": "REGION",
        "function": "Surface near a chair for placing personal items.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["side table", "end table"],
        "required_properties": ["flat_surface", "proximity_to_chair"]
      },
      {
        "id": "coffee_table",
        "entity_kind": "REGION",
        "function": "Central surface accessible to multiple people.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["coffee table", "ottoman"],
        "required_properties": ["central_location", "flat_surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_setting_on_side_table",
        "relation": "situated_on",
        "participant_roles": ["refreshment_setting", "side_table"],
        "required": true
      },
      {
        "id": "entertainment_control_on_coffee_table",
        "relation": "situated_on",
        "participant_roles": ["entertainment_control", "coffee_table"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshment_settings",
        "operation": "place_on",
        "participant_roles": ["refreshment_setting", "side_table"],
        "operation_count": 2
      },
      {
        "id": "place_remote",
        "operation": "place_on",
        "participant_roles": ["entertainment_control", "coffee_table"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "White plate on the left side table", "visual_description": "White circular dish on wooden surface"},
        {"label": "Red cups and white plate on the desk", "visual_description": "Red cylindrical vessels and white dish on dark wood table"}
      ],
      "entertainment_control": [
        {"label": "Remote control on the desk", "visual_description": "Small black rectangular device with buttons"}
      ],
      "side_table": [
        {"label": "Wooden side table next to the left chair", "visual_description": "Light wood table with shelf next to left armchair"},
        {"label": "Wooden side table next to the right chair", "visual_description": "Light wood table with shelf next to right armchair"}
      ],
      "coffee_table": [
        {"label": "Central rectangular table with green cushion", "visual_description": "Rectangular table with light green top in center of seating area"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_under_storage",
        "label": "Desk underneath area",
        "visual_description": "Dark wood table with enclosed panels below the surface",
        "reason": "Enclosed panels suggest storage compartments that could hold additional refreshment supplies or controls."
      }
    ],
    "inspection_order": [
      "desk_under_storage"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
